1: import test from 'node:test';
2: import assert from 'node:assert/strict';
3: 
4: import { createCommand, Option } from '../index.js';
5: 
6: const parse = (configure, argv) => {
7:   const command = createCommand('demo').exitOverride();
8:   configure(command);
9:   command.parse(['node', 'demo', ...argv]);
10:   return command.opts();
11: };
12: 
13: test('boolean options are absent until given, then true', () => {
14:   assert.deepEqual(parse((c) => c.option('-v, --verbose', 'be loud'), []), { verbose: false });
15:   assert.deepEqual(parse((c) => c.option('-v, --verbose', 'be loud'), ['-v']), {
16:     verbose: true,
17:   });
18:   assert.deepEqual(parse((c) => c.option('-v, --verbose', 'be loud'), ['--verbose']), {
19:     verbose: true,
20:   });
21: });
22: 
23: test('options with a required value capture that value', () => {
24:   assert.deepEqual(parse((c) => c.option('-n, --number <n>', 'a number'), ['-n', '42']), {
25:     number: '42',
26:   });
27:   assert.deepEqual(parse((c) => c.option('-n, --number <n>', 'a number'), ['--number=42']), {
28:     number: '42',
29:   });
30:   assert.deepEqual(parse((c) => c.option('-n, --number <n>', 'a number'), ['--number', '7']), {
31:     number: '7',
32:   });
33: });
34: 
35: test('defaults apply only when the option is absent', () => {
36:   assert.deepEqual(parse((c) => c.option('-p, --port <n>', 'port', '8080'), []), {
37:     port: '8080',
38:   });
39:   assert.deepEqual(parse((c) => c.option('-p, --port <n>', 'port', '8080'), ['-p', '99']), {
40:     port: '99',
41:   });
42: });
43: 
44: test('long flag names are camelcased into attribute names', () => {
45:   assert.equal(new Option('--check-updates').attributeName(), 'checkUpdates');
46:   assert.equal(new Option('-v, --verbose').attributeName(), 'verbose');
47:   assert.equal(new Option('--dry-run-only').attributeName(), 'dry-run-only');
48:   assert.deepEqual(parse((c) => c.option('--check-updates', 'check'), ['--check-updates']), {
49:     checkUpdates: true,
50:   });
51: });
52: 
53: test('option kind is reported correctly', () => {
54:   assert.equal(new Option('-v, --verbose').isBoolean(), true);
55:   assert.equal(new Option('-n, --number <n>').isBoolean(), true);
56:   assert.equal(new Option('-n, --number [n]').isBoolean(), false);
57:   assert.equal(new Option('-n, --number <n>').required, true);
58:   assert.equal(new Option('-n, --number [n]').optional, true);
59:   assert.equal(new Option('-v, --verbose').required, false);
60: });
61: 
62: test('an option recognises only its own flags', () => {
63:   const option = new Option('-n, --number <n>');
64:   assert.equal(option.is('-n'), true);
65:   assert.equal(option.is('--number'), true);
66:   assert.equal(option.is('-x'), true);
67:   assert.equal(option.is('--other'), false);
68:   assert.equal(new Option('--long-only').is('--long-only'), true);
69:   assert.equal(new Option('--long-only').is('-l'), false);
70: });
71: 
72: test('flags are split into short and long forms', () => {
73:   const both = new Option('-n, --number <n>');
74:   assert.equal(both.short, '-n');
75:   assert.equal(both.long, '--number');
76:   assert.equal(both.name(), 'number');
77:   const longOnly = new Option('--number <n>');
78:   assert.equal(longOnly.short, '--number');
79:   assert.equal(longOnly.long, '--number');
80: });
81: 
82: test('choices restrict the accepted values', () => {
83:   assert.deepEqual(
84:     parse((c) => c.addOption(new Option('--size <s>').choices(['small', 'large'])), [
85:       '--size',
86:       'small',
87:     ]),
88:     { size: 'small' },
89:   );
90:   assert.throws(() =>
