41:    *
42:    * @param {*} value
43:    * @param {string} [description]
44:    * @return {Option}
45:    */
46: 
47:   default(value, description) {
48:     this.defaultValue = value;
49:     this.defaultValueDescription = description;
50:     return this;
51:   }
52: 
53:   /**
54:    * Preset to use when option used without option-argument, especially optional but also boolean and negated.
55:    * The custom processing (parseArg) is called.
56:    *
57:    * @example
58:    * new Option('--color').default('GREYSCALE').preset('RGB');
59:    * new Option('--donate [amount]').preset('20').argParser(parseFloat);
