/**
 * Restricted Damerau-Levenshtein distance. Counts insertion, deletion,
 * substitution and a transposition of two adjacent characters as a single edit.
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function editDistance(a, b) {
  const m = a.length;
  const n = b.length;
  const d = [];
  for (let i = 0; i <= m; i++) {
    d[i] = [i];
  }
  for (let j = 0; j <= n; j++) {
    d[0][j] = j;
  }
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(
        d[i - 1][j] + 1,
        d[i][j - 1] + 1,
        d[i - 1][j - 1] + cost,
      );
      if (
        i > 1 &&
        j > 1 &&
        a[i - 1] === b[j - 2] &&
        a[i - 2] === b[j - 1]
      ) {
        d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
      }
    }
  }
  return d[m][n];
}

/**
 * Find close matches, using a Damerau-Levenshtein edit distance.
 *
 * @param {string} word
 * @param {string[]} candidates
 * @returns {string}
 */

export function suggestSimilar(word, candidates) {
  if (!candidates || candidates.length === 0) return '';

  const searchingOptions = word.startsWith('--');
  if (searchingOptions) {
    word = word.slice(2);
  }

  let bestDistance = Number.MAX_SAFE_INTEGER;
  const suggestions = [];
  const seen = new Set();

  candidates.forEach((candidate) => {
    let candidateText = candidate;
    if (searchingOptions && candidateText.startsWith('--')) {
      candidateText = candidateText.slice(2);
    }
    if (candidateText.length <= 1) return;

    const distance = editDistance(word, candidateText);
    if (distance > maxDistance) return;

    const longer = Math.max(word.length, candidateText.length);
    const similarity = (longer - distance) / longer;
    if (similarity <= 0.4) return;

    if (distance < bestDistance) {
      bestDistance = distance;
      suggestions.length = 0;
      seen.clear();
      seen.add(candidate);
      suggestions.push(candidate);
    } else if (distance === bestDistance) {
      if (!seen.has(candidate)) {
        seen.add(candidate);
        suggestions.push(candidate);
      }
    }
  });

  if (suggestions.length === 0) return '';
  suggestions.sort((a, b) => a.localeCompare(b));

  if (suggestions.length === 1) {
    const suggestion = searchingOptions ? `--${suggestions[0].slice(2)}` : suggestions[0];
    return `\n(Did you mean ${suggestion}?)`;
  }
  const list = suggestions.map((s) =>
    searchingOptions ? `--${s.slice(2)}` : s,
  );
  return `\n(Did you mean one of ${list.join(', ')}?)`;
}
